        static double[][] b(String s) {
            String[] parts = s.split(";");
            double[][] r = new double[parts.length][6];
            for (int i = 0; i < parts.length; i++) {
                String[] v = parts[i].split(",");
                for (int j = 0; j < 6; j++) {
                    r[i][j] = Double.parseDouble(v[j]);
                }
            }
            return r;
        }
